/* app.js — 裁切台交互层（依赖 opus-core.js 暴露的 window.OpusCut） */
(function () {
  'use strict';
  var OC = window.OpusCut;
  if (!OC) { document.body.innerHTML = '<p style="padding:40px;color:#e05b52">未加载 opus-core.js</p>'; return; }

  var SAMPLE_RATE = OC.SAMPLE_RATE;
  var state = { buf: null, idx: null, rows: null, plans: null, out: null };

  var $ = function (id) { return document.getElementById(id); };
  function el(tag, cls, txt) { var e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; }
  function fmtBytes(n) {
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(1) + ' KiB';
    return (n / 1048576).toFixed(2) + ' MiB';
  }
  function fmtInt(n) { return (n == null ? '—' : n.toLocaleString('en-US')); }
  function fmtSec(samples) {
    var sec = samples / SAMPLE_RATE;
    var m = Math.floor(sec / 60), s = sec - m * 60;
    return m > 0 ? m + ':' + s.toFixed(3).padStart(6, '0') : s.toFixed(3) + 's';
  }
  function fmtSample(n) { return fmtInt(n) + ' 样本 · ' + fmtSec(n); }
  function hex(n) { return '0x' + (n >>> 0).toString(16).padStart(8, '0'); }
  function hhmmssms(sample) {
    var ms = Math.round(sample / SAMPLE_RATE * 1000);
    var h = Math.floor(ms / 3600000); ms -= h * 3600000;
    var m = Math.floor(ms / 60000); ms -= m * 60000;
    var s = Math.floor(ms / 1000); ms -= s * 1000;
    return (h ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0') + '.' + String(ms).padStart(3, '0');
  }

  /* ---------------- 状态栏 / 进度 ---------------- */
  function setStatus(kind, text) {
    var p = $('statusPill'); p.className = 'pill ' + kind; $('statusText').textContent = text;
  }
  function showProgress(text, frac) {
    $('prog').classList.add('show'); $('progText').textContent = text;
    $('progBar').style.width = (frac == null ? 8 : frac * 100) + '%';
  }
  function hideProgress() { $('prog').classList.remove('show'); }
  function tick() { return new Promise(function (r) { setTimeout(r, 0); }); }

  /* ---------------- 导入 ---------------- */
  async function loadBuffer(buf, name) {
    showProgress('解析 Ogg 页与包…', 0.15); await tick();
    var t0 = performance.now();
    var idx;
    try {
      idx = OC.parse(buf);
    } catch (e) {
      hideProgress();
      state.buf = null; state.idx = null;
      setStatus('bad', '导入失败');
      toastDiag([{ kind: (e.kind === 'crc' ? 'bad' : 'bad'), offset: e.offset, msg: e.message }]);
      return;
    }
    state.buf = buf; state.idx = idx; state.name = name;
    showProgress('建立页/包索引…', 0.6); await tick();
    state.rows = OC.tabulate(idx);
    state.plans = null; state.out = null;
    hideProgress();
    var ms = performance.now() - t0;
    render(name, ms);
  }

  function render(name, ms) {
    var idx = state.idx, rows = state.rows;
    $('drop').hidden = true;
    $('cards').hidden = false;
    $('work').hidden = false;
    $('cChains').textContent = idx.chains.length;
    $('cPlay').innerHTML = fmtSec(idx.globalSamples) + ' <small>' + fmtInt(idx.globalSamples) + ' 样本</small>';
    $('cPackets').textContent = fmtInt(idx.packetCount);
    $('cPages').textContent = fmtInt(idx.pageCount);
    $('cBytes').textContent = fmtBytes(idx.byteLength);
    $('cMs').innerHTML = ms.toFixed(0) + '<small>ms</small>';

    var fatalChains = idx.chains.filter(function (c) { return c.fatal; }).length;
    var hasScanErr = !!idx.scanError;
    if (fatalChains || hasScanErr) {
      setStatus('bad', (hasScanErr ? '坏页已截断' : '') + (fatalChains ? (hasScanErr ? ' · ' : '') + fatalChains + ' 链无效' : ''));
    } else if (idx.warnings.length) {
      setStatus('warn', idx.warnings.length + ' 条提示');
    } else {
      setStatus('ok', '解析通过 · ' + name);
    }
    $('bChains').textContent = idx.chains.length;
    $('bPages').textContent = fmtInt(idx.pageCount);
    $('bPackets').textContent = fmtInt(rows.packets.length);
    buildFilters();
    renderChains();
    renderPages();
    renderPackets();
    renderDiag();
    // 定位/剪选范围
    $('locSample').max = Math.max(0, idx.globalSamples - 1);
    $('locRange').textContent = idx.globalSamples > 0 ? ('可播 0 — ' + fmtInt(idx.globalSamples - 1) + ' 样本') : '无可播音频';
    $('locOut').innerHTML = '<div class="empty">输入 48 kHz 样本位置，查看落在哪条链、哪一页、哪个包。</div>';
    $('cutS').max = idx.globalSamples; $('cutS').value = 0;
    $('cutT').max = idx.globalSamples; $('cutT').value = idx.globalSamples;
    $('cutPlans').innerHTML = ''; $('cutDl').disabled = true;
    $('cutNote').textContent = '设置 [S, T) 后点“计算”，查看每条相交链的起始包、预卷、新 pre-skip 与 EOS 粒度。';
  }

  /* ---------------- 链视图 ---------------- */
  function renderChains() {
    var idx = state.idx, box = $('chainList'); box.innerHTML = '';
    if (!idx) return;
    var total = idx.globalSamples || 1;
    idx.chains.forEach(function (ch, i) {
      var card = el('div', 'chaincard' + (ch.fatal ? ' bad' : ''));
      var h = el('h3');
      h.appendChild(el('span', null, '链 ' + ch.ordinal));
      h.appendChild(el('span', 'tag', 'serial ' + hex(ch.serial)));
      if (ch.header) {
        h.appendChild(el('span', 'tag', ch.header.channels + ' 声道'));
        h.appendChild(el('span', 'tag', ch.header.preSkip + ' pre-skip'));
      }
      h.appendChild(el('span', 'tag', ch.pages.length + ' 页'));
      h.appendChild(el('span', 'tag', (ch.audio ? ch.audio.length : 0) + ' 音频包'));
      if (ch.fatal) { var p = el('span', 'pill bad'); p.appendChild(el('span', 'dot')); p.appendChild(document.createTextNode('无效')); h.appendChild(p); }
      else if (ch.truncated) { var pt = el('span', 'pill warn'); pt.appendChild(el('span', 'dot')); pt.appendChild(document.createTextNode('坏包截断')); h.appendChild(pt); }
      card.appendChild(h);

      if (ch.fatal) {
        card.appendChild(el('div', 'note bad', '此链无效：' + ch.fatal.message + '（偏移 ' + fmtInt(ch.fatal.offset) + '）'));
        box.appendChild(card); return;
      }
      if (ch.truncated && ch.badPacket) {
        card.appendChild(el('div', 'note warn', '第 ' + ch.badPacket.packetIndex + ' 个音频包解析失败（偏移 ' + fmtInt(ch.badPacket.offset) +
          '，页序 ' + ch.badPacket.pageSeq + '）：' + ch.badPacket.message + '。已保留此前 ' + ch.audio.length +
          ' 个有效包作索引，本链不参与拼接输出。'));
      }
      var chips = el('div', 'chips');
      chips.appendChild(chip('B', fmtInt(ch.B)));
      chips.appendChild(chip('pre-skip', fmtInt(ch.header.preSkip)));
      chips.appendChild(chip('可播起点', fmtInt(ch.playStart)));
      chips.appendChild(chip('E', fmtInt(ch.E)));
      chips.appendChild(chip('可播长度', fmtInt(ch.playLen) + ' (' + fmtSec(ch.playLen) + ')'));
      chips.appendChild(chip('全局轴', fmtInt(ch.globalStart) + ' → ' + fmtInt(ch.globalEnd)));
      card.appendChild(chips);

      var bar = el('div', 'axisbar');
      var seg = el('div', 'seg');
      seg.style.left = (ch.globalStart / total * 100) + '%';
      seg.style.width = (ch.playLen / total * 100) + '%';
      seg.style.background = i % 2 ? '#3d6f9e' : '#4d86b8';
      seg.appendChild(el('span', null, '链 ' + ch.ordinal));
      bar.appendChild(seg);
      card.appendChild(bar);
      box.appendChild(card);
    });
    var legend = el('div', 'legend');
    legend.innerHTML = '<span><i style="background:#4d86b8"></i>链可播区间（按源顺序拼成全局轴）</span>';
    box.appendChild(legend);
  }
  function chip(k, v) { var c = el('span', 'chip'); c.appendChild(document.createTextNode(k + ' ')); var b = el('b', null, v); c.appendChild(b); return c; }

  /* ---------------- 页索引（虚拟分页） ---------------- */
  var PAGE_SIZE = 200;
  var pageView = { chain: 'all', q: '', offset: 0, filtered: null };

  function filteredPages() {
    var rows = state.rows.pages;
    if (pageView.chain === 'all' && !pageView.q) return rows;
    var q = pageView.q.trim().toLowerCase();
    return rows.filter(function (p) {
      if (pageView.chain !== 'all' && p.chain !== pageView.chain) return false;
      if (!q) return true;
      return String(p.off).indexOf(q) >= 0 || String(p.seq).indexOf(q) >= 0 ||
        hex(p.serial).toLowerCase().indexOf(q) >= 0 || String(p.granule).indexOf(q) >= 0;
    });
  }
  function renderPages() {
    var all = filteredPages();
    var total = all.length;
    var maxOff = Math.max(0, total - PAGE_SIZE);
    if (pageView.offset > maxOff) pageView.offset = maxOff;
    if (pageView.offset < 0) pageView.offset = 0;
    var slice = all.slice(pageView.offset, pageView.offset + PAGE_SIZE);
    var t = $('pageTable'); t.innerHTML = '';
    var thead = el('thead'), tr = el('tr');
    ['偏移', '链', '序列号', '页序', '粒度', '期望', '完成包', 'CRC', '标志'].forEach(function (x, i) {
      var th = el('th', null, x); if (i === 0) th.style.textAlign = 'left'; tr.appendChild(th);
    });
    thead.appendChild(tr); t.appendChild(thead);
    var tb = el('tbody');
    slice.forEach(function (p) {
      var r = el('tr');
      var granTxt = p.granule === -1 ? '-1' : fmtInt(p.granule);
      r.appendChild(el('td', 'l mono', fmtInt(p.off)));
      r.appendChild(el('td', null, p.chain));
      r.appendChild(el('td', 'mono', hex(p.serial)));
      r.appendChild(el('td', null, fmtInt(p.seq)));
      r.appendChild(el('td', 'mono' + (p.granuleOk === false ? ' gbad' : ''), granTxt));
      r.appendChild(el('td', 'mono dim', p.expected == null ? '—' : fmtInt(p.expected)));
      r.appendChild(el('td', null, p.completedPackets || (p.granule === -1 ? '—' : 0)));
      r.appendChild(el('td', 'mono ' + (p.crcOk ? 'ok' : 'bad'), hex(p.crc)));
      var fl = el('td', 'l'); var flags = el('span');
      if (p.bos) flags.appendChild(el('span', 'tag bos', 'BOS '));
      if (p.eos) flags.appendChild(el('span', 'tag eos', 'EOS '));
      if (p.cont) flags.appendChild(el('span', 'tag cont', '续传'));
      if (!p.bos && !p.eos && !p.cont) flags.appendChild(el('span', 'faint', '—'));
      fl.appendChild(flags); r.appendChild(fl);
      tb.appendChild(r);
    });
    t.appendChild(tb);
    renderPager('pagePager', total, pageView.offset, PAGE_SIZE, function (off) { pageView.offset = off; renderPages(); });
  }

  /* ---------------- 包索引（虚拟分页） ---------------- */
  var PKT_SIZE = 250;
  var pktView = { chain: 'all', q: '', offset: 0 };
  function filteredPackets() {
    var rows = state.rows.packets;
    if (pktView.chain === 'all' && !pktView.q) return rows;
    var q = pktView.q.trim().toLowerCase();
    return rows.filter(function (p) {
      if (pktView.chain !== 'all' && p.chain !== pktView.chain) return false;
      if (!q) return true;
      return String(p.index).indexOf(q) >= 0 || String(p.off).indexOf(q) >= 0 ||
        String(p.unt_start).indexOf(q) >= 0 || String(p.unt_end).indexOf(q) >= 0 ||
        p.pages.join(',').indexOf(q) >= 0;
    });
  }
  function renderPackets() {
    var all = filteredPackets();
    var total = all.length;
    var maxOff = Math.max(0, total - PKT_SIZE);
    if (pktView.offset > maxOff) pktView.offset = maxOff;
    if (pktView.offset < 0) pktView.offset = 0;
    var slice = all.slice(pktView.offset, pktView.offset + PKT_SIZE);
    var t = $('packetTable'); t.innerHTML = '';
    var thead = el('thead'), tr = el('tr');
    ['偏移', '链', '#', '跨页', '页', '未裁切起点', '未裁切终点', '样本', '帧', 'TOC'].forEach(function (x) {
      tr.appendChild(el('th', null, x));
    });
    thead.appendChild(tr); t.appendChild(thead);
    var tb = el('tbody');
    slice.forEach(function (p) {
      var r = el('tr');
      r.appendChild(el('td', 'l mono', fmtInt(p.off)));
      r.appendChild(el('td', null, p.chain));
      r.appendChild(el('td', null, fmtInt(p.index)));
      var sp = el('td', 'l');
      if (p.spansPages) sp.appendChild(el('span', 'tag cont', '跨 ' + p.pages.length + ' 页'));
      else sp.appendChild(el('span', 'faint', '—'));
      r.appendChild(sp);
      r.appendChild(el('td', 'mono dim l', p.pages.join(',')));
      r.appendChild(el('td', 'mono', fmtInt(p.unt_start)));
      r.appendChild(el('td', 'mono', fmtInt(p.unt_end)));
      r.appendChild(el('td', null, fmtInt(p.samples)));
      r.appendChild(el('td', null, p.frames * p.frameSamples / 48 + 'ms/' + p.frames));
      r.appendChild(el('td', 'mono dim', '0x' + p.toc.toString(16).padStart(2, '0')));
      tb.appendChild(r);
    });
    t.appendChild(tb);
    renderPager('packetPager', total, pktView.offset, PKT_SIZE, function (off) { pktView.offset = off; renderPackets(); });
  }

  function renderPager(id, total, offset, size, onChange) {
    var box = $(id); box.innerHTML = '';
    if (total <= size) { box.appendChild(el('span', 'faint', '共 ' + fmtInt(total) + ' 行')); return; }
    var start = offset + 1, end = Math.min(offset + size, total);
    box.appendChild(el('span', 'faint', fmtInt(start) + '–' + fmtInt(end) + ' / ' + fmtInt(total)));
    var prev = el('button', 'btn ghost', '‹ 上一页'); prev.disabled = offset <= 0;
    prev.addEventListener('click', function () { onChange(Math.max(0, offset - size)); });
    var next = el('button', 'btn ghost', '下一页 ›'); next.disabled = offset + size >= total;
    next.addEventListener('click', function () { onChange(offset + size); });
    box.appendChild(prev); box.appendChild(next);
    box.appendChild(el('span', 'faint', '第 ' + (Math.floor(offset / size) + 1) + ' / ' + Math.ceil(total / size) + ' 页'));
  }

  function buildFilters() {
    // 页/包两栏的链筛选与搜索
    var idx = state.idx; if (!idx) return;
    ['page', 'packet'].forEach(function (which) {
      var host = $(which + 'Filter'); if (!host) return;
      host.innerHTML = '';
      var view = which === 'page' ? pageView : pktView;
      var sel = el('select');
      var oAll = el('option', null, '全部链'); oAll.value = 'all'; sel.appendChild(oAll);
      idx.chains.forEach(function (ch) { var o = el('option', null, '链 ' + ch.ordinal + (ch.fatal ? '（无效）' : '')); o.value = String(ch.ordinal); sel.appendChild(o); });
      sel.value = view.chain;
      sel.addEventListener('change', function () { view.chain = sel.value === 'all' ? 'all' : Number(sel.value); view.offset = 0; which === 'page' ? renderPages() : renderPackets(); });
      var q = el('input'); q.type = 'text'; q.placeholder = which === 'page' ? '搜索偏移/页序/序列号/粒度' : '搜索包号/偏移/样本';
      q.value = view.q; q.style.width = '220px';
      var timer = null;
      q.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(function () { view.q = q.value; view.offset = 0; which === 'page' ? renderPages() : renderPackets(); }, 160); });
      host.appendChild(el('span', 'fl', '筛选'));
      host.appendChild(sel); host.appendChild(q);
    });
  }
  /* ---------------- 定位 ---------------- */
  function doLocate() {
    var idx = state.idx; if (!idx) return;
    var out = $('locOut');
    var raw = $('locSample').value.trim();
    if (raw === '') { out.innerHTML = '<div class="empty">请输入样本位置。</div>'; return; }
    var s = Number(raw);
    if (!isFinite(s) || s < 0) { out.innerHTML = '<div class="empty bad">请输入不小于 0 的整数样本。</div>'; return; }
    s = Math.floor(s);
    if (s >= idx.globalSamples) {
      out.innerHTML = '<div class="empty bad">超出可播范围：全局轴共 ' + fmtInt(idx.globalSamples) + ' 样本（0 — ' + fmtInt(idx.globalSamples - 1) + '）。</div>';
      return;
    }
    var loc = OC.locate(idx, s);
    if (!loc) { out.innerHTML = '<div class="empty bad">该样本不属于任何可播链。</div>'; return; }
    var ch = loc.chain;
    // 找该样本所在的包（按未裁切区间）
    var absGran = ch.playStart + loc.local;      // 链粒度坐标
    var pkt = null;
    for (var i = 0; i < ch.audio.length; i++) {
      var a = ch.audio[i];
      if (absGran >= a.unt_start && absGran < a.unt_end) { pkt = a; break; }
    }
    // 所在页：结束点包含该样本的页，或按包 lastPage
    var page = pkt ? idx.pages[pkt.pkt.lastPage] : null;
    var box = el('div');
    var kv = el('div', 'kv');
    function add(k, v, cls) { kv.appendChild(el('div', 'k', k)); var d = el('div', 'v' + (cls ? ' ' + cls : '')); if (v instanceof Node) d.appendChild(v); else d.textContent = v; kv.appendChild(d); }
    add('所在链', '第 ' + ch.ordinal + ' 条 · serial ' + hex(ch.serial) + ' · ' + ch.header.channels + ' 声道');
    add('链内可播位置', fmtInt(loc.local) + ' / ' + fmtInt(ch.playLen) + ' · ' + hhmmssms(loc.local));
    add('链粒度坐标', fmtInt(absGran));
    if (pkt) {
      add('所在音频包', '#' + pkt.index + ' · 偏移 ' + fmtInt(pkt.pkt.off) + ' · ' + pkt.samples + ' 样本');
      add('未裁切区间', '[' + fmtInt(pkt.unt_start) + ', ' + fmtInt(pkt.unt_end) + ')');
      add('包内偏移', fmtInt(absGran - pkt.unt_start) + ' 样本');
      var pagesNode = el('span');
      pkt.pkt.pages.forEach(function (pi, k) {
        if (k) pagesNode.appendChild(document.createTextNode(' → '));
        var gp = idx.pages[pi];
        pagesNode.appendChild(el('b', null, '第 ' + gp.seq + ' 页'));
      });
      if (pkt.pkt.spansPages) pagesNode.appendChild(el('span', 'tag cont', ' 跨页拼包'));
      add('跨过的页', pagesNode);
      if (page) add('结束页', '第 ' + page.seq + ' 页 · 偏移 ' + fmtInt(page.off) + ' · 粒度 ' + fmtInt(page.granuleRaw));
    } else {
      add('所在音频包', '—（样本落在预跳过区或末尾裁量区）');
    }
    out.innerHTML = ''; out.appendChild(kv);
    // 高亮该包在包索引中的行
    var rows = $('packetTable').querySelectorAll('tbody tr');
    var ci = 0;
    for (var c = 0; c < ch.ordinal; c++) ci += state.idx.chains[c].audio ? state.idx.chains[c].audio.length : 0;
    if (pkt) {
      var rowIdx = ci + pkt.index;
      rows.forEach(function (r) { r.style.background = ''; });
      if (rows[rowIdx]) rows[rowIdx].style.background = '#243447';
    }
  }

  /* ---------------- 剪选 ---------------- */
  function readCut() {
    var idx = state.idx;
    var S = Math.floor(Number($('cutS').value));
    var T = Math.floor(Number($('cutT').value));
    if (!isFinite(S) || S < 0) S = 0;
    if (!isFinite(T) || T > idx.globalSamples) T = idx.globalSamples;
    return { S: Math.max(0, S), T: Math.min(idx.globalSamples, T) };
  }
  function computeCut() {
    var idx = state.idx; if (!idx) return;
    var r = readCut();
    $('cutPlans').innerHTML = ''; $('cutDl').disabled = true; state.plans = null; state.out = null;
    if (!(r.T > r.S)) { $('cutNote').textContent = '终点 T 必须大于起点 S。'; return; }
    var sel;
    try { sel = OC.select(idx, r.S, r.T); }
    catch (e) { $('cutNote').textContent = '无法计算：' + e.message; return; }
    state.plans = sel.plans; state.cutRange = r;
    if (sel.plans.length === 0) {
      $('cutNote').textContent = '所选区间没有可输出的音频链。' + (sel.skipped.length ? '（' + sel.skipped.length + ' 条链被跳过）' : '');
      return;
    }
    $('cutNote').textContent = '区间 [' + fmtInt(r.S) + ', ' + fmtInt(r.T) + ') · ' + fmtSec(r.T - r.S) +
      ' · 相交链 ' + sel.plans.length + ' 条' + (sel.skipped.length ? '，跳过 ' + sel.skipped.length + ' 条' : '') +
      '。每条链独立输出头与 EOS，按源顺序连接。';
    var total = idx.globalSamples || 1;
    var list = el('div');
    sel.plans.forEach(function (p) {
      var card = el('div', 'chaincard');
      var h = el('h3');
      h.appendChild(el('span', null, '输出链 · 源链 ' + p.chainIndex));
      h.appendChild(el('span', 'tag', p.chain.header.channels + ' 声道'));
      h.appendChild(el('span', 'tag', p.packets.length + ' 包'));
      card.appendChild(h);
      var chips = el('div', 'chips');
      chips.appendChild(chip('区间', '[' + fmtInt(p.Si) + ', ' + fmtInt(p.Ti) + ')'));
      chips.appendChild(chip('新原点 K', fmtInt(p.K)));
      chips.appendChild(chip('新 pre-skip', fmtInt(p.preSkip)));
      chips.appendChild(chip('EOS 粒度', fmtInt(p.eosGranule)));
      chips.appendChild(chip('起始包', '#' + p.startIdx));
      chips.appendChild(chip('终止包', '#' + p.endIdx));
      chips.appendChild(chip('末包裁量', fmtInt(p.trim) + ' 样本'));
      if (p.startIdx > 0) {
        var prev = p.chain.audio[p.startIdx - 1];
        var gap = p.Si - prev.unt_start;
        chips.appendChild(chip('预卷', fmtInt(Math.min(gap, OC.PREROLL)) + ' 样本' + (gap < OC.PREROLL ? ' (链首)' : '')));
      } else {
        chips.appendChild(chip('预卷', '链首'));
      }
      card.appendChild(chips);
      var bar = el('div', 'axisbar');
      var seg = el('div', 'seg'); seg.style.left = (p.chain.globalStart / total * 100) + '%';
      seg.style.width = (p.chain.playLen / total * 100) + '%'; seg.style.background = '#334a63';
      bar.appendChild(seg);
      var a = Math.max(p.Si - p.chain.playStart, 0), b = Math.min(p.Ti - p.chain.playStart, p.chain.playLen);
      var sel2 = el('div', 'sel');
      sel2.style.left = ((p.chain.globalStart + a) / total * 100) + '%';
      sel2.style.width = ((b - a) / total * 100) + '%';
      bar.appendChild(sel2);
      card.appendChild(bar);
      list.appendChild(card);
    });
    var legend = el('div', 'legend');
    legend.innerHTML = '<span><i style="background:#334a63"></i>源链可播区间</span><span><i style="background:#4c9be8"></i>本次剪选</span>';
    list.appendChild(legend);
    $('cutPlans').appendChild(list);
    // 预生成下载字节
    try {
      state.out = OC.buildOutput(idx, sel.plans);
      $('cutDl').disabled = false;
    } catch (e) {
      $('cutDl').disabled = true;
      $('cutNote').textContent += ' 生成失败：' + e.message;
    }
  }

  function download() {
    if (!state.out) return;
    var blob = new Blob([state.out.data], { type: 'audio/ogg' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    var base = (state.name || 'cut').replace(/\.[^.]+$/, '');
    var r = state.cutRange || { S: 0, T: 0 };
    a.href = url; a.download = base + '_' + r.S + '-' + r.T + '.opus';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 2000);
  }

  /* ---------------- 诊断 ---------------- */
  function diagItems() {
    var idx = state.idx, items = [];
    if (!idx) return items;
    // 坏页/截断：只要扫描有错，就是首要问题
    if (idx.scanError) {
      items.push({ kind: 'bad', offset: idx.scanError.offset,
        msg: '坏页：' + idx.scanError.message + '。扫描在此偏移停止，保留此前 ' + idx.pageCount + ' 个有效页。' });
    }
    // 链级失败：当扫描错误已覆盖同一区域时不再重复报告缺失 EOS
    idx.chains.forEach(function (ch) {
      if (!ch.fatal) return;
      if (idx.scanError && ch.fatal.kind === 'eos') return; // 由坏页/截断统一说明
      items.push({ kind: 'bad', offset: ch.fatal.offset, msg: '链 ' + ch.ordinal + '：' + ch.fatal.message });
    });
    idx.warnings.forEach(function (w) {
      // 与扫描错误同偏移、且属于派生结果的缺失 EOS 不再单列
      if (idx.scanError && w.kind === 'missing-eos' && w.offset === idx.scanError.offset) return;
      var kind = (w.kind === 'crc' || w.kind === 'bad-packet' || w.kind === 'truncated' || w.kind === 'capture') ? 'bad'
        : (w.kind === 'granule' || w.kind === 'seq-gap' || w.kind === 'missing-eos' || w.kind === 'serial-switch') ? 'warn' : 'info';
      items.push({ kind: kind, offset: w.offset, msg: w.msg });
    });
    if (!items.length) items.push({ kind: 'ok', offset: null, msg: '未发现坏页、坏包或截断；各链粒度一致。' });
    return items;
  }
  function renderDiag() {
    var box = $('diagList'); box.innerHTML = '';
    var items = diagItems();
    var problems = items.filter(function (it) { return it.kind !== 'ok'; }).length;
    $('bDiag').textContent = problems || '';
    items.forEach(function (it) {
      var row = el('div', 'diagitem ' + it.kind);
      row.appendChild(el('span', 'off', it.offset == null ? '' : '@' + fmtInt(it.offset)));
      row.appendChild(el('span', 'msg', it.msg));
      box.appendChild(row);
    });
  }
  function toastDiag(items) {
    // 导入失败时也把诊断显示出来
    $('drop').hidden = true; $('cards').hidden = true; $('work').hidden = false;
    $('bChains').textContent = '0'; $('bPages').textContent = '0'; $('bPackets').textContent = '0'; $('bDiag').textContent = String(items.length);
    switchTab('diag');
    var box = $('diagList'); box.innerHTML = '';
    items.forEach(function (it) {
      var row = el('div', 'diagitem bad');
      row.appendChild(el('span', 'off', it.offset == null ? '' : '@' + fmtInt(it.offset)));
      row.appendChild(el('span', 'msg', it.msg));
      box.appendChild(row);
    });
  }

  /* ---------------- Tab 切换 ---------------- */
  function switchTab(name) {
    document.querySelectorAll('.tab').forEach(function (t) { t.classList.toggle('active', t.dataset.pane === name); });
    document.querySelectorAll('.pane').forEach(function (p) { p.classList.toggle('active', p.id === 'pane-' + name); });
  }

  /* ---------------- 事件 ---------------- */
  function bind() {
    $('file').addEventListener('change', function (e) {
      var f = e.target.files && e.target.files[0]; if (!f) return;
      var rd = new FileReader();
      showProgress('读取文件…', 0.04);
      rd.onload = function () { hideProgress(); loadBuffer(new Uint8Array(rd.result), f.name); };
      rd.onerror = function () { hideProgress(); setStatus('bad', '读取失败'); };
      rd.readAsArrayBuffer(f);
    });
    $('drop').addEventListener('click', function (e) { if (e.target.tagName !== 'INPUT') $('file').click(); });
    ['dragenter', 'dragover'].forEach(function (ev) {
      $('drop').addEventListener(ev, function (e) { e.preventDefault(); $('drop').classList.add('drag'); });
    });
    ['dragleave', 'drop'].forEach(function (ev) {
      $('drop').addEventListener(ev, function (e) { e.preventDefault(); $('drop').classList.remove('drag'); });
    });
    $('drop').addEventListener('drop', function (e) {
      var f = e.dataTransfer.files && e.dataTransfer.files[0]; if (!f) return;
      var rd = new FileReader(); showProgress('读取文件…', 0.04);
      rd.onload = function () { hideProgress(); loadBuffer(new Uint8Array(rd.result), f.name); };
      rd.readAsArrayBuffer(f);
    });
    document.querySelectorAll('.tab').forEach(function (t) {
      t.addEventListener('click', function () { switchTab(t.dataset.pane); });
    });
    $('demoBtn').addEventListener('click', function () { loadDemo('tone'); });
    $('demoMultiBtn').addEventListener('click', function () { loadDemo('multi'); });
    $('locGo').addEventListener('click', doLocate);
    $('locSample').addEventListener('keydown', function (e) { if (e.key === 'Enter') doLocate(); });
    $('cutGo').addEventListener('click', computeCut);
    $('cutAll').addEventListener('click', function () {
      $('cutS').value = 0; $('cutT').value = state.idx ? state.idx.globalSamples : 0;
    });
    $('cutDl').addEventListener('click', download);
  }

  /* ---------------- 样例 ---------------- */
  var DEMO_TONE = '';
  var DEMO_MULTI = '';
  function b64ToBytes(b64) {
    var bin = atob(b64); var n = bin.length; var out = new Uint8Array(n);
    for (var i = 0; i < n; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  function loadDemo(which) {
    var b64 = which === 'multi' ? DEMO_MULTI : DEMO_TONE;
    showProgress('解码样例…', 0.1);
    setTimeout(function () {
      hideProgress();
      loadBuffer(b64ToBytes(b64), which === 'multi' ? 'demo-multi.opus' : 'tone.opus');
    }, 30);
  }

  bind();
  // 导出少量内部以便调试
  window.__cut = { state: state, OC: OC };
})();
